"""Учебные условия МОАИП. Все численные данные примеров условные."""

def C(given, states, result, answer, code=None):
    return dict(given=given, states=states, result=result, answer=answer, code=code)

def Q(title, terms, mechanism, visual, worked, changed, practice, question, pitfall, source):
    return dict(title=title, terms=terms, mechanism=mechanism, visual=visual, worked=worked,
                changed=changed, practice=practice, question=question, pitfall=pitfall, source=source)

def table(columns, rows, caption):
    return dict(type='comparison', columns=columns, rows=rows, caption=caption)

def process(items, caption):
    return dict(type='process', items=[dict(title=a,text=b) for a,b in items],caption=caption)

def network(nodes, edges, caption):
    return dict(type='network',nodes=[dict(id=a,title=b,text=c) for a,b,c in nodes],edges=[dict(from_=a,to=b,label=c) for a,b,c in edges],caption=caption)

